p=once(p,'function setPending(id){const p=ensureProgress();if(!p)return false;p.pendingStory=id||null;persist();return true;}function completeStory(id){const p=ensureProgress();if(!p)return false;const first=!p.completedStories.includes(id);if(first)p.completedStories.push(id);if(p.pendingStory===id)p.pendingStory=null;if(id===INTRO_STORY_ID){p.introCompleted=true;state.introSeen=true;}persist();if(first&&typeof window.showCivilizationCalamityUnlockNoticeForStory==="function")queueMicrotask(()=>window.showCivilizationCalamityUnlockNoticeForStory(id));if(first&&typeof window.handleSecondWorldStoryCompletion==="function")window.handleSecondWorldStoryCompletion(id);return true;}','function setPending(id){const p=ensureProgress();if(!p)return false;p.pendingStory=id||null;persist();return true;}function completeStory(id){const p=ensureProgress();if(!p)return false;const thirdGate=thirdWorldStoryCompletionGate(id,state);if(thirdGate.handled&&thirdGate.allowed!==true)return false;const first=!p.completedStories.includes(id);if(first)p.completedStories.push(id);if(p.pendingStory===id)p.pendingStory=null;if(id===INTRO_STORY_ID){p.introCompleted=true;state.introSeen=true;}if(thirdGate.handled)applyThirdWorldStoryCompletion(id,state,thirdGate);persist();if(first&&typeof window.showCivilizationCalamityUnlockNoticeForStory==="function")queueMicrotask(()=>window.showCivilizationCalamityUnlockNoticeForStory(id));if(first&&typeof window.handleSecondWorldStoryCompletion==="function")window.handleSecondWorldStoryCompletion(id);return true;}','complete story')
